from typing import List, Dict, Tuple, Any, Union
if not isinstance(metrics, list):
    raise ValueError("Metrics must be a list")

metric_names = []
metric_params_list = []

for metric in metrics:
    if isinstance(metric, str):
        metric_names.append(metric)
        metric_params_list.append({})
    elif isinstance(metric, dict):
        if 'name' not in metric:
            raise ValueError("Metric dictionary must contain 'name' key")
        metric_names.append(metric['name'])
        params = metric.copy()
        params.pop('name', None)
        metric_params_list.append(params)
    else:
        raise ValueError(f"Invalid metric type: {type(metric)}. Must be str or dict")

return metric_names, metric_params_list

