def _parse_value(s: str) -> int:
    s = s.strip()
    if '%' in s:
        percent = float(s.replace('%', '')) / 100
        return max(1, int(round(num_clauses * percent)))
    return int(s)

if '<' in spec:
    parts = [p.strip() for p in spec.split('<')]
    if len(parts) != 2:
        raise ValueError(f"Invalid min_should_match spec: {spec}")
    val1 = _parse_value(parts[0])
    val2 = _parse_value(parts[1])
    return min(val1, val2)

result = _parse_value(spec)
return max(0, min(result, num_clauses))

